# Owner(s): ["oncall: package/deploy"]
# [MODULE DOC] Tests that package archives generated by an older version (stored in the
# package_bc directory next to this file) can still be loaded. Import-time side effect: computes
# that directory path. Falls back to a non-relative import of the shared base test case.

from pathlib import Path
from unittest import skipIf

from torch.package import PackageImporter
from torch.testing._internal.common_utils import IS_FBCODE, IS_SANDCASTLE, run_tests


try:
    from .common import PackageTestCase
except ImportError:
    # Support the case where we run this file directly.
    from common import PackageTestCase

packaging_directory = f"{Path(__file__).parent}/package_bc"


class TestLoadBCPackages(PackageTestCase):
    # [CLASS DOC] Backwards-compatibility loading tests; each test is skipped under fbcode or
    # sandcastle and opens one stored archive.
    """Tests for checking loading has backwards compatibility"""

    @skipIf(
        IS_FBCODE or IS_SANDCASTLE,
        "Tests that use temporary files are disabled in fbcode",
    )
    def test_load_bc_packages_nn_module(self):
        # [FUNCTION DOC] Opens the stored nn module archive and unpickles the resource named
        # nn_module.pkl from the nn_module package. Passes if loading raises no error; nothing
        # is asserted on the result.
        """Tests for backwards compatible nn module"""
        importer1 = PackageImporter(f"{packaging_directory}/test_nn_module.pt")
        importer1.load_pickle("nn_module", "nn_module.pkl")

    @skipIf(
        IS_FBCODE or IS_SANDCASTLE,
        "Tests that use temporary files are disabled in fbcode",
    )
    def test_load_bc_packages_torchscript_module(self):
        # [FUNCTION DOC] Opens the stored TorchScript module archive and unpickles
        # torchscript_module.pkl. Passes if loading raises no error; nothing is asserted on
        # the result.
        """Tests for backwards compatible torchscript module"""
        importer2 = PackageImporter(f"{packaging_directory}/test_torchscript_module.pt")
        importer2.load_pickle("torchscript_module", "torchscript_module.pkl")

    @skipIf(
        IS_FBCODE or IS_SANDCASTLE,
        "Tests that use temporary files are disabled in fbcode",
    )
    def test_load_bc_packages_fx_module(self):
        # [FUNCTION DOC] Opens the stored FX module archive and unpickles fx_module.pkl. Passes
        # if loading raises no error; nothing is asserted on the result.
        """Tests for backwards compatible fx module"""
        importer3 = PackageImporter(f"{packaging_directory}/test_fx_module.pt")
        importer3.load_pickle("fx_module", "fx_module.pkl")


if __name__ == "__main__":
    run_tests()
